    41  function buildOldDotURL(url: string, shortLivedAuthToken?: string): Promise<string> {
    42      const hashIndex = url.lastIndexOf('#');
    43      const hasHashParams = hashIndex !== -1;
    44      const hasURLParams = url.indexOf('?') !== -1;
    45      let originURL = url;
    46      let hashParams = '';
    47      if (hasHashParams) {
    48          originURL = url.substring(0, hashIndex);
    49          hashParams = url.substring(hashIndex);
    50      }
    51
    52      const authTokenParam = shortLivedAuthToken ? `authToken=${shortLivedAuthToken}` : '';
    53      const emailParam = `email=${encodeURIComponent(currentUserEmail)}`;
    54      const paramsArray = [authTokenParam, emailParam];
    55      const params = paramsArray.filter(Boolean).join('&');
    56
    57      return Environment.getOldDotEnvironmentURL().then((environmentURL) => {
    58          const oldDotDomain = Url.addTrailingForwardSlash(environmentURL);
    59
    60          // If the URL contains # or ?, we can assume they don't need to have the `?` token to start listing url parameters.
    61          return `${oldDotDomain}${originURL}${hasURLParams ? '&' : '?'}${params}${hashParams}`;
    62      });
    63  }
