    12  type LinkProps = {
    13      /** Link to open in new tab */
    14      href: string;
    15
    16      onPress?: undefined;
    17  };
    18
    19  type PressProps = {
    20      href?: undefined;
    21
    22      /** Overwrites the default link behavior with a custom callback */
    23      onPress: (event: GestureResponderEvent | KeyboardEvent) => void;
    24  };
    25
    26  type TextLinkProps = (LinkProps | PressProps) &
    27      TextProps & {
    28          /** Additional style props */
    29          style?: StyleProp<TextStyle>;
    30
    31          /** Callback that is called when mousedown is triggered */
    32          onMouseDown?: MouseEventHandler;
    33      };
    34
    35  function TextLink({href, onPress, children, style, onMouseDown = (event) => event.preventDefault(), ...rest}: TextLinkProps, ref: ForwardedRef<RNText>) {
    36      const {environmentURL} = useEnvironment();
    37      const styles = useThemeStyles();
    38
    39      const openLink = (event: GestureResponderEvent | KeyboardEvent) => {
    40          if (onPress) {
    41              onPress(event);
    42          } else {
    43              Link.openLink(href, environmentURL);
    44          }
    45      };
    46
    47      const openLinkOnTap = (event: GestureResponderEvent) => {
    48          event.preventDefault();
    49
    50          openLink(event);
    51      };
    52
    53      const openLinkOnEnterKey: KeyboardEventHandler = (event) => {
    54          if (event.key !== 'Enter') {
    55              return;
    56          }
    57          event.preventDefault();
    58
    59          openLink(event);
    60      };
    61
    62      return (
    63          <Text
    64              style={[styles.link, style]}
    65              role={CONST.ROLE.LINK}
    66              href={href}
    67              onPress={openLinkOnTap}
    68              onKeyDown={openLinkOnEnterKey}
    69              onMouseDown={onMouseDown}
    70              ref={ref}
    71              suppressHighlighting
    72              // eslint-disable-next-line react/jsx-props-no-spreading
    73              {...rest}
    74          >
    75              {children}
    76          </Text>
    77      );
    78  }
    79
    80  TextLink.displayName = 'TextLink';
    81
    82  export type {LinkProps, PressProps};
    83
    84  export default forwardRef(TextLink);
